WITH customer_revenue AS (
 SELECT l.customer_id, SUM(l.revenue) AS total_revenue
 FROM loads l
 GROUP BY l.customer_id
), top_customers AS (
 SELECT customer_id, total_revenue
 FROM customer_revenue
 ORDER BY total_revenue DESC
 LIMIT 10
)
SELECT (
 SELECT SUM(tc.total_revenue) FROM top_customers tc
) / NULLIF(
 (SELECT SUM(cr.total_revenue) FROM customer_revenue cr), 0
) * 100 AS top_10_customers_percentage;
